"const fs = require('fs');
let html = fs.readFileSync('d:/AI/Antigravity/index.html', 'utf8');

// Normalize multi-line tags: replace line breaks inside <...> with spaces
html = html.replace(/<[^>]+>/gs, (match) => {
    return match.replace(/\r?\n/g, ' ');
});

const lines = html.split('\n');
let openTags = [];

for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const tagRegex = /<\/?([a-zA-Z0-9:-]+)(?:\s+[^>]*?)?>/g;
    let match;
    while ((match = tagRegex.exec(line)) !== null) {
        const fullTag = match[0];
        const tagName = match[1].toLowerCase();

        if (fullTag.startsWith('</')) {
            const indexInStack = openTags.map(t => t.tag).lastIndexOf(tagName);
            if (indexInStack !== -1) {
                openTags.splice(indexInStack);
            }
        } else if (!fullTag.endsWith('/>') && !['img', 'br', 'hr', 'input', 'meta', 'link'].includes(tagName)) {
            openTags.push({ tag: tagName, line: i + 1 });
        }
    }

    if (i + 1 === 3395) {
        console.log('Open tags at line 3395:', openTags.map(t => `${t.tag}(${t.line})`));
    }
}
console.log('Final open tags at end of file:', openTags.map(t => `${t.tag}(${t.line})`));
